SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·卷261·郭琼传·后汉任职", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/aecd425b6a5c2b61245e92470190e94829f2d494/content/books/zizhi-tongjian/vol-289/year-0950/part-01/sources/library/songshi-261-guo-qiong-han/source.txt", "note": "《宋史》卷261·郭琼传·后汉任职，段落 songshi-9c6e46fee832-p058012；已核上下文及传主，纸本及异文待核。", "id": "858f6f3b-4c99-57df-97e5-7fbdea9f2b8c"}, {"title": "宋史·卷261·郭琼传·籍贯与早年", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/aecd425b6a5c2b61245e92470190e94829f2d494/content/books/zizhi-tongjian/vol-289/year-0950/part-01/sources/library/songshi-261-guo-qiong-origin/source.txt", "note": "《宋史》卷261·郭琼传·籍贯与早年，段落 songshi-9c6e46fee832-p058010；已核上下文及传主，纸本及异文待核。", "id": "8a2c3628-e4b3-50fd-bb44-d56beb486815"}, {"title": "资治通鉴·卷289·乾祐三年·正月、二月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/aecd425b6a5c2b61245e92470190e94829f2d494/content/books/zizhi-tongjian/vol-289/year-0950/part-01/sources/library/tongjian-289-950-opening/source.txt", "note": "《资治通鉴》卷289·乾祐三年·正月、二月及追述，段落 zizhi-tongjian-a63549944a71-p003427；已核上下文及传主，纸本及异文待核。", "id": "3a4d2d31-adf1-59a5-b0ea-9e608dbdb27a"}, {"title": "旧五代史·卷103·隐帝本纪·乾祐三年正月奏报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/00a00dec3e96e2d090e708b0dd9446e64b281f10/content/books/zizhi-tongjian/vol-288/year-0949/part-06/sources/library/jiuwudaishi-103-january-950-reports/source.txt", "note": "《旧五代史》卷103·隐帝本纪·乾祐三年正月奏报，段落 jiu-wudaishi-205deb4a7860-p002483；已核上下文及传主，纸本及异文待核。", "id": "79349ac2-c735-5498-aa2f-079985404fc6"}, {"title": "旧五代史·卷101·隐帝本纪·乾祐元年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b8ce7838037279cfbdd88a95bcd6fb9f26236396/content/books/zizhi-tongjian/vol-288/year-0948/part-09/sources/library/jiuwudaishi-101-december-948/source.txt", "note": "《旧五代史》卷101·隐帝本纪·乾祐元年十二月，段落 jiu-wudaishi-205deb4a7860-p002462；已核上下文及传主，纸本及异文待核。", "id": "931e2b3e-52d4-50a6-b465-da07f4acc580"}]'::jsonb)
