INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "王万敢", "aliases": ["王萬敢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉密州刺史。949年十二月攻击南唐海州获水镇；《旧五代史》次年正月也载他在海州方向的奏报，镇名作荻水，地名及是否同次行动仍待校核。生卒年未载。", "biography": null, "status": "draft", "id": "0e0fb3d0-08be-5b24-8bc6-9cb76e19259a"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "郭琼", "aliases": ["郭瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉将领，曾任沂州刺史。950年正月奉命担任东路行营都部署，率禁军和齐州兵支援王万敢。《宋史》郭琼传记其为平州卢龙人，但对密州战事的叙述与通鉴不同，分别保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "2bb6c55b-0b36-5f0b-9c32-5bc865efa268"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "李金全", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李金全，前节度使、多次献马者。", "biography": null, "status": "draft", "id": "13205047-3c88-59d8-9900-ef435bd6e59a"}, {"name": "刘彦贞", "aliases": ["劉彥貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘信之子，南唐楚州刺史。944年条下追述他改任濠州观察使，迅速前往替代刘崇俊。具体任职年月与生卒年未载。", "biography": null, "status": "draft", "id": "3a86e5c0-cc8e-5120-888d-a75e599e8e30"}, {"name": "李弘冀", "aliases": ["弘冀", "李冀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟的长子。943年七月条下被立为南昌王。姓名在《资治通鉴》作弘冀，《新五代史》同一册封作冀；沿用同一主体，不因姓名省写再建李冀。生卒年尚未核。", "biography": null, "status": "draft", "id": "e4027731-d3e9-5cd1-8c58-d504f38025da"}, {"name": "周宗", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：周宗。", "biography": null, "status": "draft", "id": "155e76cd-ab0e-5e2a-a791-43d64ebe4669"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

