ription": "后汉朝廷制止郭威此次率兵临边的请求。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "80aef0bf-8ac5-5209-b09b-80012162fdb2"}, {"title": "后汉派使者收葬河中、凤翔的战死者和饿死者遗骸", "start_year": 950, "end_year": 950, "time_original": "950年正月丙寅", "dynasty": "五代十国", "description": "后汉派使者收葬河中、凤翔的战死者和饿死者遗骸。", "phases": [], "location_name": "河中、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7c6fc507-9bd4-5f9d-b5cb-43f59e6185cb"}, {"title": "史书记僧人已收集大量遗骸", "start_year": null, "end_year": null, "time_original": "950年正月丙寅收葬诏令时，已完成收集；起始时间未载", "dynasty": "五代十国", "description": "史书记僧人已收集大量遗骸。", "phases": [], "location_name": "河中、凤翔战区，具体收集地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3193865a-bdac-57b3-9eae-0c66cf35efcd"}, {"title": "李璟得知后汉平定三镇叛乱后，撤销李金全的北面招讨职务", "start_year": 950, "end_year": 950, "time_original": "950年正月条下，具体日未载", "dynasty": "五代十国", "description": "李璟得知后汉平定三镇叛乱后，撤销李金全的北面招讨职务。", "phases": [], "location_name": "南唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7551343d-471c-57cd-913e-28de1ae8966a"}, {"title": "史书记刘彦贞搜敛民财，贿赂权贵", "start_year": null, "end_year": null, "time_original": "刘彦贞长期任职寿州期间的追述，具体起止未载", "dynasty": "五代十国", "description": "史书记刘彦贞搜敛民财，贿赂权贵。", "phases": [], "location_name": "寿州及南唐权贵所在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0f8fed3c-a20b-5252-ac25-84c796e48106"}, {"title": "史书记受贿权